#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){string s,t;cin>>s>>t;
if(s.size()!=t.size()){printf("NO\n");return 0;}
int m1[256],m2[256];memset(m1,-1,sizeof(m1));memset(m2,-1,sizeof(m2));
for(size_t i=0;i<s.size();++i){
int x=s[i],y=t[i];
if(m1[x]==-1)m1[x]=y;else if(m1[x]!=y){printf("NO\n");return 0;}
if(m2[y]==-1)m2[y]=x;else if(m2[y]!=x){printf("NO\n");return 0;}}
printf("YES\n");return 0;}

